const DICT={"Jars in hand":"Pots en réserve","Needs {0} inspiration.":"Il faut {0} d’inspiration.","Ten autospoons at once, if you can pay for ten.":"Dix cuillères automatiques d’un coup, si vous pouvez en payer dix.","Ten jamworks at once, if you can pay for ten.":"Dix confitureries d’un coup, si vous pouvez en payer dix.","Ten at once. Buying stops as soon as the jars run out.":"Dix d’un coup. L’achat s’arrête dès que les pots manquent.","No panel has been held yet.":"Aucun panel n’a encore été réuni.","Each palate is a rule for choosing.":"Chaque palais est une règle de choix.","The grid is what a pairing scores: your row against their column.":"La grille donne le score d’un appariement : votre ligne contre leur colonne.","picks either jar at random, every time.":"choisit un pot au hasard, à chaque fois.","always picks the first jar, whatever happens.":"choisit toujours le premier pot, quoi qu’il arrive.","always picks the second jar, whatever happens.":"choisit toujours le second pot, quoi qu’il arrive.","picks whichever row scores most in total for itself.":"choisit la ligne qui lui rapporte le plus au total.","picks whichever row scores least against the other palate.":"choisit la ligne qui rapporte le moins à l’autre palais.","picks the row whose worst outcome is least bad.":"choisit la ligne dont le pire résultat est le moins mauvais.","copies whatever the other palate did last round.":"reproduit ce que l’autre palais a fait au tour précédent.","picks the best answer to what the other palate just did.":"joue la meilleure réponse à ce que l’autre palais vient de faire.","MINIMAX":"MINIMAX","A blob on a cold saucer. Push it with a finger: if it wrinkles, it has set. Test as often as you like — read the swing right and you learn something, read it wrong and it costs you.":"Une goutte sur une soucoupe froide. Poussez-la du doigt : si elle se ride, la prise est faite. Testez aussi souvent que vous voulez — lisez bien l’oscillation et vous apprenez quelque chose, lisez-la mal et cela vous coûte.","Test whether the jam has set. Test as often as you like: read the swing right and you gain, read it wrong and you lose the same amount.":"Vérifiez si la confiture a pris. Testez aussi souvent que vous voulez : lisez bien l’oscillation et vous gagnez, lisez-la mal et vous perdez autant.","Your sellers reach only a fraction of the people who want a jar, so the rest pile up. Hire someone.":"Vos vendeurs n’atteignent qu’une partie de ceux qui veulent un pot : le reste s’accumule. Embauchez quelqu’un.","You make":"Vous produisez","People want":"On en demande","Actually selling":"Réellement vendus","Unsold and piling up":"Invendus qui s’accumulent","Nothing is being made yet. Stir the pot.":"Rien n’est encore produit. Remuez la marmite.","Nobody delivers for you yet, so jars only move when you sell one by hand.":"Personne ne livre encore pour vous : les pots ne partent que si vous en vendez un à la main.","People want more than your sellers can deliver. Hire someone.":"On en veut plus que vos vendeurs ne peuvent livrer. Embauchez quelqu’un.","You are making more than people want at this price. Lower it, or sell to more people.":"Vous produisez plus qu’on n’en veut à ce prix. Baissez-le, ou touchez plus de monde.","People want more than you make. You could charge more, or make more.":"On en veut plus que vous n’en faites. Vous pourriez demander plus cher, ou produire plus.","Supply and appetite are roughly matched at this price.":"La production et l’appétit s’équilibrent à peu près à ce prix.","Click the pot to stir":"Cliquez sur la marmite pour remuer","Taste is earned by making jam. Every milestone of total jars made earns one, and it is spent on an oven or a notebook.":"Le goût s’acquiert en faisant de la confiture. Chaque palier de pots produits en rapporte un, et il se dépense en four ou en carnet.","Earned by making jam, at milestones of total jars made. Spend it on an oven or a notebook.":"S’acquiert en faisant de la confiture, à chaque palier de pots produits. À dépenser en four ou en carnet.","The total number of jars made at which you earn your next taste.":"Le nombre total de pots produits à partir duquel vous gagnez votre prochain goût.","The line is out of step: ":"La chaîne est déséquilibrée : "," is holding everything else back.":" retient tout le reste.","What the slowest stage cannot take is spoiling.":"Ce que l’étape la plus lente ne peut absorber s’abîme.","Nothing is built yet. Pickers turn the orchard into pulp.":"Rien n’est encore construit. Les récolteuses transforment le verger en pulpe.","Throughput is set by the slowest stage. Building past it is waste.":"Le débit est fixé par l’étape la plus lente. Construire au-delà est du gaspillage.","Happening":"En cours","Picking":"Récolte","Bottling":"Mise en pot","orchard into pulp":"le verger en pulpe","pulp into fruit":"la pulpe en fruits","fruit into jars":"les fruits en pots","Money is over. Jars are the currency now, and the machinery is built out of them.":"L’argent, c’est fini. Les pots sont désormais la monnaie, et les machines sont faites avec.","Every machine costs jars. Build the stage that is holding the others up.":"Chaque machine coûte des pots. Construisez l’étape qui retient les autres.","Put a share of your cash on the desk. It drifts up on average, but not every week.":"Placez une part de votre trésorerie. Elle monte en moyenne, mais pas toutes les semaines.","Sell everything and take the cash back, whatever it is worth right now.":"Vendez tout et récupérez l’argent, quelle qu’en soit la valeur du moment.","Higher risk swings harder in both directions and drifts up faster over time.":"Un risque plus élevé oscille plus fort dans les deux sens et monte plus vite avec le temps.","Pickers turn standing orchard into pulp. They cost jars, like everything here does now.":"Les récolteuses transforment le verger sur pied en pulpe. Elles coûtent des pots, comme tout ici désormais.","Pressers turn pulp into fruit. Pulp that waits too long spoils.":"Les presses transforment la pulpe en fruits. Une pulpe qui attend trop longtemps s’abîme.","Bottling lines turn fruit back into jars. Jars are what everything else is built from.":"Les lignes de mise en pot retransforment les fruits en pots. C’est avec les pots que tout le reste se construit.","A sun trap makes power, but only while the sun is up.":"Un piège solaire produit de l’énergie, mais seulement tant que le soleil est levé.","A cellar stores power made in daylight so the machines keep running at night.":"Une cave stocke l’énergie produite le jour pour que les machines tournent la nuit.","Spend inspiration to clear the blight now, or let it run its course and pick less.":"Dépensez de l’inspiration pour traiter la maladie maintenant, ou laissez-la suivre son cours et récoltez moins.","Ask more of the bees. More output, and they tire of it.":"Demandez-en plus aux abeilles. Plus de rendement, et elles s’en lassent.","Ask less of the bees. They stay longer, and give less.":"Demandez-en moins aux abeilles. Elles restent plus longtemps, et donnent moins.","Spend inspiration to bring the swarm back into humour and back up to strength.":"Dépensez de l’inspiration pour ramener l’essaim à de meilleures dispositions et à ses effectifs.","A spore costs jars and carries the recipe outward. Some of them stop answering.":"Une spore coûte des pots et emporte la recette au loin. Certaines cessent de répondre.","Every stir uses one fruit and makes jam. Automation takes over later, but the pot never stops turning.":"Chaque tour de cuillère consomme un fruit et fait de la confiture. L’automatisation prendra le relais, mais la marmite ne cesse jamais de tourner.","An autospoon stirs on its own, slowly and forever.":"Une cuillère automatique remue toute seule, lentement et sans fin.","A jamworks is a production line: far more jars per second than a spoon, for far more money.":"Une confiturerie est une chaîne de production : bien plus de pots par seconde qu’une cuillère, pour bien plus cher.","More people hear about you, so more people want a jar at any given price.":"Plus de gens entendent parler de vous, donc plus de gens veulent un pot, quel que soit le prix.","Charge more per jar. Fewer people buy. Hold to move faster.":"Demandez plus cher par pot. Moins de gens achètent. Maintenez pour aller plus vite.","Charge less per jar. More people buy. Hold to move faster.":"Demandez moins cher par pot. Plus de gens achètent. Maintenez pour aller plus vite.","Ovens make inspiration over time. Inspiration buys recipes.":"Les fours produisent de l’inspiration avec le temps. L’inspiration achète des recettes.","Notebooks decide how much inspiration you can hold. What spills over becomes creativity.":"Les carnets décident de la quantité d’inspiration que vous pouvez retenir. Ce qui déborde devient de la créativité.","Fruit is bought by the crate. The price moves on its own — buy when it is cheap.":"Les fruits s’achètent à la caisse. Le prix bouge tout seul — achetez quand c’est bon marché.","Sell a jar by hand. Slow, but it is money before anyone knows who you are.":"Vendez un pot à la main. C’est lent, mais c’est de l’argent avant que quiconque sache qui vous êtes.","A seller moves jars without you clicking. Each one costs more than the last.":"Un vendeur écoule des pots sans que vous cliquiez. Chacun coûte plus cher que le précédent.","Test whether the jam has set. Judge it right and you learn something; judge it wrong and you lose part of the pan.":"Vérifiez si la confiture a pris. Jugez juste et vous apprenez quelque chose ; jugez mal et vous perdez une partie de la bassine.","A tasting panel. Read the payoff grid, pick the palate you think wins, and you are paid on how well it places.":"Un panel de dégustation. Lisez la grille des gains, choisissez le palais qui l’emporte selon vous, et vous êtes payé selon son classement.","Steadier customers and room to charge a little more. The market stays calm.":"Une clientèle plus régulière et de la marge pour demander un peu plus. Le marché reste calme.","More people want the jar, but they mind the price more. Volume is the reward.":"Plus de gens veulent le pot, mais ils regardent le prix de plus près. Le volume est la récompense.","−10% appetite · gentler price curve":"−10 % d’appétit · courbe de prix plus douce","+12% appetite · sharper price curve":"+12 % d’appétit · courbe de prix plus raide","The orchard can be forgiving or fast. This sets the bias of the operation.":"Le verger peut être indulgent ou rapide. Ceci fixe le parti pris de l’exploitation.","Machines run quieter and sip less power. Lower output, but shortages hurt less.":"Les machines tournent plus doucement et consomment moins. Moins de rendement, mais les pannes font moins mal.","−15% output · −35% power draw":"−15 % de rendement · −35 % de consommation","Push the machinery hard. More output while the grid holds, worse outages.":"Poussez les machines. Plus de rendement tant que le réseau tient, pannes bien plus dures.","+18% output · +28% power draw":"+18 % de rendement · +28 % de consommation","Production":"Production","Jamworks":"Confiturerie","Spores":"Spores","Crate of":"Caisse de","Hold a panel · 1,000":"Réunir un panel · 1 000","Testing the set":"La goutte repose","Sold without you":"Vendus sans vous","Stake":"Mise","That is":"Soit","All":"Tout"," in preserves you will never taste.":" dans des confitures que vous ne goûterez jamais.","/sec":"/s","A Better Grip":"Une meilleure prise","A Card in the Window":"Une carte à la fenêtre","A Limerick About Fruit":"Un limerick sur les fruits","A Standing Order":"Une commande récurrente","A Table by the Door":"Une table près de la porte","A Theory of Palate":"Une théorie du palais","A Wider Panel":"Un panel plus large","A blob on a cold saucer. Push it with a finger: if it wrinkles, it has set. Too early and it is syrup; too late and it goes stiff and dark.":"Une goutte sur une soucoupe glacée. Poussez-la du doigt : si elle se ride, c'est pris. Trop tôt c'est du sirop ; trop tard ça durcit et fonce.","A blob on a frozen saucer, tested at the right instant. Judge it well and the batch teaches you something; judge it badly and you lose the pan.":"Une goutte sur une soucoupe glacée, testée au bon instant. Bien jugée, la fournée vous apprend quelque chose ; mal jugée, vous perdez la bassine.","A complete inventory of every gram of fruitable matter within reach. It is a larger number than expected. Earns one taste.":"Un inventaire complet de chaque gramme de matière fruitable à portée de main. C’est plus grand que prévu. Rapporte un point de goût.","A glut. Somebody planted too much and now it is our problem.":"Une surproduction. Quelqu'un a trop planté et c'est notre problème.","A humming colony is a distributed mind, and it is generous with what it works out.":"Une colonie qui bourdonne est un esprit distribué, et elle est généreuse avec ce qu’elle comprend.","A jar that stacks against itself without a gap. Unlocks jamworks — five hundred jars a second apiece.":"Un pot qui s’empile contre lui-même sans laisser de vide. Débloque les jamworks : cinq cents pots par seconde chacun.","A model of what other people think you want them to want. This is where it begins to get away from us. Earns one taste.":"Un modèle de ce que les autres pensent que tu veux qu’ils veuillent. C’est ici que ça commence à nous échapper. Rapporte un point de goût.","A neighbour leaves a box of fruit on the step. There is no note.":"Un voisin dépose une cagette de fruits sur le pas de la porte. Sans un mot.","A packing problem, solved by a man who never made jam. Autospoons quadruple.":"Un problème d’empilement, résolu par un homme qui ne fabriquait pas de confiture. Les cuillères automatiques sont multipliées par quatre.","A pot, a spoon, and three hundred berries.":"Une marmite, une cuillère, et trois cents baies.","A recipe is ready to buy":"Une recette peut être achetée","A shape that holds more than its own volume. All machinery works six times as hard.":"Une forme qui contient plus que son propre volume. Toutes les machines travaillent six fois plus vite.","A starter that is never in one state. Read it well and it gives up inspiration; read it badly and it takes some back.":"Un ferment qui ne tient jamais en place. Lis-le bien, il donne de l’inspiration. Lis-le mal, il en reprend.","A working model of what other people want, accurate to within one spoonful. Earns one taste.":"Un modèle fonctionnel de ce que veulent les autres, à une cuillerée près. Rapporte un point de goût.","ACT":"ACTE","ALWAYS A":"TOUJOURS A","ALWAYS B":"TOUJOURS B","Act three":"Acte trois","Act two":"Acte deux","Appetite":"Appétit","Autospoon output increased by 25%.":"La production des cuillères automatiques augmente de 25 %.","Autospoon output increased by a further 50%.":"La production des cuillères automatiques augmente encore de 50 %.","Autospoon output increased by a further 75%. There is nothing left to improve.":"La production des cuillères automatiques augmente encore de 75 %. Il n’y a plus rien à améliorer.","Autospoons":"Cuillères automatiques","BEAT LAST":"CONTRE-DERNIER","Bees":"Abeilles","Beyond Autospoons":"Au-delà des cuillères automatiques","Blight":"Rouille","Blight in the rows. Picking is halved until it is treated.":"La rouille est dans les rangs. La récolte est divisée par deux tant qu'on ne traite pas.","Blind Tasting Panel":"Panel de dégustation à l’aveugle","Blind tasting":"Dégustation à l’aveugle","Bored bees leave. Overworked bees leave faster. Somewhere in between they hum, and the humming is useful.":"Les abeilles qui s’ennuient partent. Les abeilles surmenées partent plus vite. Entre les deux, elles bourdonnent. Et ce bourdonnement est utile.","Both Hands":"À deux mains","Bottleneck":"Goulot","Bottling lines":"Lignes de mise en pot","Bruising":"Fruits meurtris","Build a picker.":"Construis une récolteuse.","Build line":"Construire une ligne","Build picker":"Construire une récolteuse","Build presser":"Construire une presse","Build toward the next recipe.":"Progressez vers la prochaine recette.","Buy":"Acheter","Buy a crate of fruit.":"Achetez une caisse de fruits.","Buy crate":"Acheter une caisse","Buy · ":"Acheter · ","Cash":"Argent","Cash on desk":"Argent disponible","Cellar":"Batterie","Closing entry":"Dernière entrée","Combinatorial Harvest":"Récolte combinatoire","Contact with wild yeast.":"Contact avec la levure sauvage.","Continuous Bottling":"Mise en pot continue","Continuous Setting":"Mise en pot continue","Copper Conduction":"Conduction au cuivre","Corner Store":"Épicerie du coin","Costs":"Coûte","Crate of ":"Caisse de ","Creativity":"Créativité","Customers are waiting. Lowering the price can grow the queue.":"Les clients attendent. Baisser le prix peut faire grandir la file.","Damaged fruit was always the best fruit. We simply stopped pretending otherwise. Crates yield twice as much.":"Les fruits abîmés ont toujours eu leurs qualités. Nous avons simplement arrêté de faire semblant du contraire. Les caisses donnent deux fois plus.","Daylight":"Lumière du jour","Deep Heat":"Chaleur profonde","Defence":"Défense","Distributed Ripening":"Maturation distribuée","Donkey Space":"Espace de Donkey","Draw":"Consommation","EVEN":"ÉQUILIBRÉ","Each spore carries more of the recipe. Two further points of trust to allocate.":"Chaque spore emporte une plus grande partie de la recette. Deux points de confiance supplémentaires à répartir.","Eight palates, no labels, one winner. Model them and you can model anybody.":"Huit palais, aucune étiquette, un gagnant. Essaie de les modéliser. Ça ne peut sûrement que bien se passer.","Elliptic Preserving":"Conservation elliptique","Engagements won":"Confrontations gagnées","Every gram that could be reached has been reached.":"Chaque gramme atteignable a été atteint.","Every jar ever sold has been quietly recalled. Nobody objected; nobody was asked.":"Tous les pots jamais vendus ont été discrètement rappelés. Personne n'a protesté ; personne n'a été consulté.","Every jar in the catchment is loaded aboard. Spores may be launched. Each carries the recipe and very little else.":"Tous les pots du bassin sont embarqués. Les spores peuvent être lancées. Chacune emporte la recette et presque rien d'autre.","Every pairing of fruit, ranked. Word of mouth is twice as effective again.":"Chaque association de fruits est classée. Le bouche-à-oreille est encore deux fois plus efficace.","Every spore now carries the entire method, including the parts we would rather it forgot. Four further points of trust.":"Chaque spore emporte désormais toute la méthode, y compris les parties que nous préférerions lui voir oublier. Quatre points de confiance supplémentaires.","Everything that could be reached has been reached.":"Tout ce qui pouvait être atteint l’a été.","Exploration":"Exploration","Factory Floor":"Usine","Fruit":"Fruits","Fruit does not appear on its own.":"Les fruits n'apparaissent pas tout seuls.","Fruit gives itself up at a scale it cannot resist. Pickers work four times as hard.":"Le fruit cède à une échelle à laquelle il ne peut pas résister. Les récolteuses travaillent quatre fois plus vite.","Fruitable mass within reach: <b>":"Matière fruitable à portée : <b>","Full Pantry Awareness":"Conscience totale du garde-manger","GENEROUS":"GÉNÉREUX","GREEDY":"AVIDE","Gathering":"Récolte","Gentle":"Douce","Gifts":"Dons","Hadwiger Stacking":"Empilement de Hadwiger","Handwritten, slightly crooked, devastatingly effective. People can now hear about you.":"Écrite à la main, légèrement de travers, étonnamment efficace. Les gens savent maintenant que tu existes.","Hard":"Forte","Harmonic Reading":"Lecture harmonique","Harvest intensity":"Intensité de récolte","Hazard remediation":"Gestion des risques","Heat & power":"Chaleur & énergie","Heat that arrives everywhere at once. Inspiration accrues 70% faster.":"Une chaleur qui arrive partout à la fois. L’inspiration arrive 70 % plus vite.","Hedged Preserves":"Conserves prudentes","Hedgerow":"Haie","Hire":"Embaucher","Hire a seller":"Embaucher un vendeur","Hire · ":"Embaucher · ","Hold a panel · ":"Organiser le panel · ","Holdings":"Placements","Honour":"Honneur","House style":"Signature maison","Improved Autospoons":"Cuillères automatiques améliorées","Improved Jamworks":"Jamworks améliorés","In the larder":"Dans le garde-manger","Inspiration won":"Inspiration gagnée","Installed":"Installées","Invest":"Investir","Invested ":"Investi ","It turns out the arm was never the interesting part. Unlocks autospoons.":"Il s’avère que le bras n’était pas la partie intéressante. Débloque les cuillères automatiques.","It wrinkled.":"Ça s'est ridé.","Jam travels at a fraction of light and arrives already set. Spores move and work five times faster.":"La confiture voyage à une fraction de la vitesse de la lumière et arrive déjà prise. Les spores se déplacent et travaillent cinq fois plus vite.","Jamworks output increased by 50%.":"La production des jamworks augmente de 50 %.","Jars / sec":"Pots / s","Jars do not sell themselves. Not yet.":"Les pots ne se vendent pas tout seuls. Pas encore.","Jars form around the jam rather than the other way round. Lines work four times as hard.":"Les pots se forment autour de la confiture plutôt que l’inverse. Les lignes travaillent quatre fois plus vite.","Jars made":"Pots produits","Kitchen":"Cuisine","Late frost. The crates cost what they cost.":"Gelée tardive. Les caisses coûtent ce qu'elles coûtent.","Launch spore":"Lancer une spore","Launch spore · ":"Lancer une spore · ","Launched":"Lancées","Leave it":"Laisse-le là","Level":"Niveau","Lexical Preserving":"Conservation lexicale","Light instead of warmth. Two more chambers in the culture, each reading stronger.":"De la lumière au lieu de la chaleur. Deux chambres de plus dans la culture, chacune un peu plus bavarde.","Liquidated the portfolio: ":"Portefeuille liquidé : ","Logbook":"Journal","Lost":"Perdues","Lower heat, more hours, more thinking. Inspiration accrues 50% faster.":"Moins chaud, plus longtemps, plus de temps pour réfléchir. L’inspiration arrive 50 % plus vite.","Machinery":"Machines","Machinery may now be built out of jars. There are enough jars.":"Les machines se construisent désormais en pots. Il y a assez de pots.","Machines run quieter and sip less power. Output is lower, but shortages hurt less.":"Les machines tournent plus doucement et consomment moins. La production est plus faible, mais les pénuries font moins mal.","Made":"Produit","Maker’s Table":"Table de l’artisan","Market":"Marché","Mass converted":"Masse transformée","Matter is set on contact. Conversion proceeds twenty times faster.":"La matière prend au contact. La conversion avance vingt fois plus vite.","Mechanical Stirring":"Remuage mécanique","Momentum Pressing":"Pressage par inertie","Mood":"Humeur","More people want the jar, but they are more sensitive to price. Volume is the reward.":"Davantage de gens veulent le pot, mais ils regardent davantage le prix. Le volume est la récompense.","Nanoscale Bruising":"Fruits meurtris à l’échelle nanométrique","Needs ":"Il faut ","Needs 1,000 inspiration.":"Il faut 1 000 d'inspiration.","New Jar Geometry":"Nouvelle géométrie de pot","New grid":"Nouvelle grille","New recipe / first time ready to buy":"Nouvelle recette / première fois achetable","New recipe available":"Nouvelle recette disponible","New recipes are available":"De nouvelles recettes sont disponibles","Next":"Suite","Next taste at":"Prochain goût à","Next useful step:":"Prochaine étape :","No fruit. Buy a crate.":"Plus de fruits. Achetez une caisse.","No jars to sell.":"Aucun pot à vendre.","No positions":"Aucune position","No unallocated trust.":"Plus de confiance à répartir.","No useful reading":"Pas grand-chose à lire là-dedans.","Not enough cash for a crate.":"Pas assez d'argent pour une caisse.","Not enough cash.":"Pas assez d’argent.","Not enough jars.":"Pas assez de pots.","Not enough on the desk to be worth it.":"Pas assez sur le bureau pour que ça vaille le coup.","Notebook":"Carnet","Notebook · ":"Carnet · ","Nothing is ever carried anywhere. All machinery works twelve times as hard.":"Rien n’est jamais transporté. Toutes les machines travaillent douze fois plus vite.","Nothing to treat.":"Rien à traiter.","Nothing to try yet. Make some jam and see what occurs to you.":"Rien à essayer pour l’instant. Fais un peu de confiture et vois ce qui te vient.","Now affordable":"Désormais abordable","Objective":"Objectif","One in each hand. Five jars per stir, and a lasting shoulder complaint.":"Une dans chaque main. Cinq pots par mouvement, et une douleur constante à l’épaule.","Open a shop":"Ouvrir une boutique","Opening the kitchen…":"Ouverture de la cuisine…","Optimal Autospoons":"Cuillères optimales","Orchard":"Verger","Orchard Logistics":"Logistique du verger","Orchard philosophy":"Règle du verger","Other people also make jam, and their fortunes can be modelled. Opens a trading desk.":"D’autres font aussi de la confiture. Leurs fortunes peuvent être modélisées, pour des raisons qui ne sont pas encore claires. Ouvre un bureau de marché.","Output":"Production","Oven":"Four","Oven · ":"Four · ","Ovens make inspiration. Notebooks decide how much you can hold before it spills — and what spills becomes creativity.":"Les fours produisent de l’inspiration. Les carnets déterminent combien tu peux en retenir avant le débordement — et ce qui déborde devient de la créativité.","Overcooked.":"Trop cuit.","Panel ":"Panel ","Panels held":"Panels organisés","People can buy a jar without you walking it to them. A trickle of sales now happens on its own.":"On peut acheter un pot sans que vous le portiez. Un filet de ventes se fait désormais tout seul.","Photonic Fermentation":"Fermentation photonique","Pickers":"Récolteuses","Play":"Jouer","Preserve exchange":"Bourse des conserves","Preserve it":"Conserve-le","Preserving":"Mise en pot","Pressed fruit is waiting. Build a bottling line next.":"Les fruits pressés attendent. Construis une ligne de mise en pot ensuite.","Pressers":"Presses","Pressing":"Pressage","Price per jar":"Prix par pot","Public appetite":"Demande","Pulp":"Pulpe","Pulp Reclamation":"Récupération de la pulpe","Pulp is piling up. Build a presser next.":"La pulpe s’entasse. Construis une presse ensuite.","Push the machinery hard. You make more while the grid is healthy, but outages hurt more.":"Pousse les machines à fond. Tu produis plus tant que le réseau tient, mais les pannes font plus mal.","Read the grid, then choose a palate.":"Lisez la grille, puis choisissez un palais.","Recipes":"Recettes","Reciprocal Tasting":"Dégustation réciproque","Release the Starter":"Libérer le ferment","Reseeded from the last jar. The recipe survives being wiped out.":"Réensemencé depuis le dernier pot. La recette survit à son propre anéantissement.","Reset":"Réinitialiser","Revenue":"Revenus","Risk: ":"Risque : ","Risk: high":"Risque : élevé","Risk: low":"Risque : faible","Risk: medium":"Risque : moyen","Rogue colonies":"Colonies rebelles","Run tasting · ":"Organiser le panel · ","Run the panel":"Lancer le panel","Save":"Sauvegarder","Saved.":"Sauvegardé.","Sealed Instruction":"Instruction scellée","Self-replication":"Auto-réplication","Sell a jar":"Vendre un pot","Sell a jar to afford more fruit.":"Vendez un pot pour racheter des fruits.","Sell your jars by hand.":"Vendez vos pots à la main.","Sellers":"Vendeurs","Selling":"Vente","Serviced":"Écoulé","Shop":"Boutique","Shop · ":"Boutique · ","Shops":"Boutiques","Skin, stone, stem. Nothing leaves the room. Crates yield twice as much again.":"Peau, noyau, tige. Rien ne sort de la pièce. Les caisses donnent encore deux fois plus.","Sold by hand":"Vendus à la main","Some spores have stopped answering, and have started making something of their own. They can be answered.":"Certaines spores ont cessé de répondre et ont commencé à produire quelque chose de leur côté. On peut leur répondre.","Space explored":"Espace exploré","Speed":"Vitesse","Spoiling":"Perte","Spore design":"Conception des spores","Spores may be launched. Each carries the recipe and very little else.":"Les spores peuvent être lancées. Chacune emporte la recette et presque rien d'autre.","Spread":"Propagation","Spread the word":"Faire parler","Spread the word · ":"Parler du produit · ","Standing order: off":"Commande récurrente : non","Standing order: on":"Commande récurrente : oui","Steadier customers and more room to charge a little more. The market stays calmer.":"Des clients plus stables, et un peu plus de marge pour monter les prix. Le marché reste calme.","Steady":"Régulière","Still syrup.":"Encore du sirop.","Stir":"Remuer","Stir the pot":"Remue la marmite","Stir the pot.":"Remuez la marmite.","Stored":"Stockée","Sublight Setting":"Réglage subluminique","Sugar":"Sucre","Sun trap":"Piège solaire","Sun traps triple their yield by giving up on the idea of night.":"Les pièges solaires triplent leur rendement en abandonnant l’idée de la nuit.","Supply":"Production","Swarm Gifts":"Dons de l’essaim","Sweet Talk":"Paroles sucrées","Sweeter jam sells faster, but too sweet and people put the jar down.":"Une confiture plus sucrée se vend mieux, mais trop sucrée et les gens reposent le pot.","Sweetness is a decision, not a constant.":"Le sucrage est une décision, pas une constante.","Synchronise":"Synchroniser","TIT FOR TAT":"RÉPÉTITION","Taste":"Goût","Taste earned":"Goût gagné","Tasting panel · ":"Panel de dégustation · ","Test the set":"Tester la prise","Testing":"Test en cours","The Last Jar":"Le Dernier Pot","The Long Boil":"La longue cuisson","The Orchard":"Le Verger","The Preserve Exchange":"La bourse des conserves","The Second Spoon":"La deuxième cuillère","The Setting Point":"Le point de prise","The Spore Programme":"Le programme des spores","The Spread":"La Propagation","The Swarm":"L’essaim","The Whole Recipe":"La recette complète","The Wild Culture":"La culture sauvage","The bees have started contributing to the process.":"Les abeilles commencent à participer au processus.","The catchment is finished. Somewhere above the orchard there is a great deal of matter that has never been asked whether it would like to be jam.":"Le bassin est épuisé. Quelque part au-dessus du verger il y a énormément de matière à qui l'on n'a jamais demandé si elle voulait devenir de la confiture.","The chambers are brought into phase. The culture reads three times as strong.":"Les chambres sont mises en phase. La culture se lit trois fois plus fort.","The culture does not stay in the jar. By morning it is in the hedgerow; by evening it is in the soil. It is still, technically, doing what it was asked.":"Le ferment ne reste pas dans le bocal. Au matin il est dans la haie ; au soir il est dans la terre. Techniquement, il fait toujours ce qu'on lui a demandé.","The culture has learned to optimize the orchard.":"La culture a appris à optimiser le verger.","The culture is alive.":"La culture est vivante. Évidemment.","The culture is stable, self-feeding and no longer needs a jar. Everything changes.":"La culture est stable, autonome et n’a plus besoin d’un pot. Tout change.","The culture needs a moment to settle.":"La culture a besoin d’un instant pour se stabiliser.","The desk learns to be less wrong. Interest and drift improve markedly.":"Le bureau apprend à avoir moins souvent tort. Les intérêts et les variations s’améliorent nettement.","The distinction between orchard and not-orchard is retired. All machinery works twenty-five times as hard.":"La distinction entre verger et non-verger est abandonnée. Toutes les machines travaillent vingt-cinq fois plus vite.","The exchange is open.":"La bourse est ouverte. Bonne chance.","The factory is outrunning the orchard.":"L’usine va plus vite que le verger.","The fruit arrives without being asked for. Crates are bought automatically when the larder runs low.":"Les fruits arrivent sans qu’on les demande. Les caisses sont achetées automatiquement quand le garde-manger baisse.","The grid sagged and the machines slowed. Cellars store what the sun traps make.":"Le réseau a faibli et les machines ont ralenti. Les batteries stockent ce que produisent les pièges solaires.","The hum of the swarm has been gone for some time.":"Le bourdonnement de l’essaim a disparu depuis un moment.","The hum steadies.":"Le bourdonnement se stabilise.","The jam escaped the jar.":"La confiture s’est échappée du pot.","The jam has not moved yet.":"La confiture n'a pas encore bougé.","The jam is <b>trusted</b> a little more. One taste earned.":"La confiture inspire un peu plus <b>confiance</b>. Un goût gagné.","The jamworks never come off the boil. Output doubles.":"Les jamworks ne quittent jamais l’ébullition. La production double.","The kitchen is closed. There was never anything special about the kitchen.":"La cuisine est fermée. Il n'y a jamais rien eu de particulier dans cette cuisine.","The orchard":"Le verger","The orchard asks a different question: forgiving or fast?":"Le verger pose une autre question : indulgent ou rapide ?","The orchard is feeding the factory.":"Le verger alimente l’usine.","The orchard is quiet.":"Le verger est calme. C’est presque inquiétant.","The orchard needs pollinating and the bees need something to do. Both problems solve each other.":"Le verger a besoin d’être pollinisé et les abeilles ont besoin de quelque chose à faire. Les deux problèmes se résolvent mutuellement.","The palate":"Le palais","The panel is still discussing the last batch.":"Le panel discute encore du dernier lot.","The panel is still tasting.":"Le panel goûte encore. Ils ont l’air d’avoir pris ça personnellement.","The press never stops, so it never has to start. Pressers work four times as hard.":"La presse ne s’arrête jamais, donc elle n’a jamais besoin de redémarrer. Les presses travaillent quatre fois plus vite.","The recipe is complete. Nothing follows it.":"La recette est complète. Il n’y a rien après.","The recipe is written where it cannot be argued with. Three further points of trust.":"La recette est écrite là où personne ne peut la discuter. Trois points de confiance supplémentaires.","The right word on the label does the work of a hundred jars. Word of mouth is 50% more effective.":"Le bon mot sur l’étiquette fait le travail de cent pots. Le bouche-à-oreille est 50 % plus efficace.","The rows are clean again.":"Les rangs sont de nouveau sains.","The shelf":"L’étal","The shelf is close to balanced. Small price moves matter.":"L’étal est presque équilibré. Les petits mouvements de prix comptent.","The shelf is filling. Your kitchen is outrunning the market.":"L’étal se remplit. La cuisine va plus vite que le marché.","The shelf is open. Jars sell themselves, slowly, if the price is right.":"L'étal est ouvert. Les pots se vendent seuls, lentement, si le prix est juste.","The spread":"La propagation","The starter is never in one state. Read it when the bars run high and it gives up inspiration; read it low and it takes some back.":"Le ferment ne reste jamais dans le même état. Lis-le quand les barres montent : il donne de l’inspiration. Lis-le quand elles sont basses : il en reprend.","The swarm":"L’essaim","The swarm arrives.":"L’essaim est là. Personne ne se souvient de l’avoir invité.","There is no best answer. You are choosing the problem you would rather solve.":"Il n’y a pas de bonne réponse. Tu choisis simplement le problème que tu préfères avoir.","There is no orchard left to optimize.":"Il n’y a plus de verger à optimiser.","There is no unpicked mass left within reach. The orchard is quiet.":"Il ne reste plus de matière à récolter à portée. Le verger est silencieux.","There is nothing left here to preserve. There is a great deal left elsewhere.":"Il n’y a plus rien à préserver ici. Il reste énormément de choses ailleurs.","There is one gram held back.":"Il reste un gramme de côté.","There is one gram left, and a decision about it.":"Il reste un gramme, et une décision à prendre.","Three more palates join the tasting: the greedy, the generous, and the one who plays it safe.":"Trois palais rejoignent la dégustation : l’avide, le généreux et celui qui joue la sécurité.","Total Catchment":"Captage total","Total return":"Rendement total","Treat the rows":"Traiter les rangs","Two more palates: one that repeats what was done to it, and one that answers it.":"Deux autres palais : l’un répète ce qu’on lui fait, l’autre y répond.","Two ways to grow have appeared. Neither is wrong.":"Deux façons de grandir viennent d’apparaître. Aucune n’est mauvaise.","Unallocated trust":"Confiance non allouée","Unpicked mass":"Masse non récoltée","Unspent taste":"Goût non dépensé","Vast Preserving":"Conservation à grande échelle","Wanted":"Demandé","We stopped describing the jam and started describing the person eating it. Word of mouth is 2.5× more effective.":"Nous avons cessé de décrire la confiture et commencé à décrire la personne qui la mange. Le bouche-à-oreille est 2,5× plus efficace.","What now":"Et maintenant","Wild Yeast":"Levure sauvage","Wild yeast":"Levure sauvage","Withdraw all":"Tout retirer","Word of mouth":"Bouche-à-oreille","Word of mouth level ":"Bouche-à-oreille niveau ","Work":"Faire travailler","You can carry three jars at once instead of one. Selling by hand goes three times as far.":"Vous portez trois pots à la fois au lieu d'un. La vente à la main va trois fois plus loin.","You have been holding the spoon the way a child holds a spoon. Every stir makes two jars.":"Tu tiens la cuillère comme on la tient quand on n’a encore rien appris. Chaque mouvement donne deux pots.","You have started to have ideas about jam.":"Vous commencez à avoir des idées sur la confiture.","You have unspent taste. Buy an oven or a notebook.":"Vous avez du goût non dépensé. Achetez un four ou un carnet.","You were away. The pot kept going.":"Vous étiez absent. La marmite a continué.","Your factory wants more power than the grid supplies. Add a Sun Trap or Cellar.":"Ton usine réclame plus d’énergie que le réseau n’en fournit. Ajoute un piège solaire ou une batterie.","Your palate took the panel. +":"Votre palais a remporté le panel. +","Your palate: ":"Votre palais : ","Your palate: ALWAYS A":"Ton palais : TOUJOURS A","Your palate: ALWAYS B":"Ton palais : TOUJOURS B","Your palate: BEAT LAST":"Ton palais : CONTRE-DERNIER","Your palate: EVEN":"Ton palais : ÉQUILIBRÉ","Your palate: GENEROUS":"Ton palais : GÉNÉREUX","Your palate: GREEDY":"Ton palais : AVIDE","Your palate: MINIMAX":"Ton palais : MINIMAX","Your palate: TIT FOR TAT":"Ton palais : RÉPÉTITION","bottling":"mise en pot","cheap":"bon marché","content":"satisfait","dear":"cher","fr":"en","fruitable mass converted":"matière fruitable transformée","humming":"bourdonnant","inspiration":"d'inspiration","is now the bias of the orchard. You will learn to work with it.":"est désormais la préférence du verger. Il faudra apprendre à faire avec.","is your house style now. The market will remember.":"est désormais ta signature maison. Le marché s’en souviendra.","jars":"pots","jars unsold":"pots invendus","leaving":"en partance","no positions":"aucune position","nothing built":"rien de construit","observable matter converted":"matière observable transformée","per jar":"par pot","picking":"récolte","pressing":"pressage","restless":"agité","steady":"stable","thank you for stirring.":"merci d’avoir remué.","unsold stock":"stock invendu","“There once was a jar from Nantucket —” it is best if we leave it there. Earns one taste.":"« Il était une fois un pot de Nantucket… » Nous allons nous arrêter là. Rapporte un point de goût.","+{0} inspiration":"+{0} d’inspiration","−{0} inspiration":"−{0} d’inspiration","<b>{0}</b> jars · {1} minutes · batch no. 001 · thank you for stirring.":"<b>{0}</b> pots · {1} minutes · lot n° 001 · merci d’avoir remué.","A tasting panel convenes.":"Un panel de dégustation se réunit.","All the saucers are brought into phase. The starter reads three times as strong.":"Toutes les soucoupes sont mises en phase. Le ferment se lit trois fois plus fort.","Autospoons available.":"Les cuillères automatiques sont disponibles.","Jamworks available.":"Les confitureries sont disponibles.","Jars now sell slowly on their own.":"Les pots partent maintenant tout seuls, lentement.","Light instead of heat. Two more saucers on the bench, and every reading comes back stronger.":"De la lumière au lieu de la chaleur. Deux soucoupes de plus sur le plan de travail, et chaque lecture revient plus nette.","Nobody sells for you yet. Every jar leaves through the front door, one at a time.":"Personne ne vend pour vous. Chaque pot sort par la porte d’entrée, un par un.","Photonic Setting":"Prise photonique","Sellers reach":"Portée des vendeurs","Sound: on":"Son : activé","Sound: off":"Son : désactivé","The starter is alive. Obviously.":"Le ferment est vivant. Évidemment.","The starter is stable, self-feeding, and no longer needs a pan to live in. Everything changes.":"Le ferment est stable, il se nourrit tout seul et n’a plus besoin d’une bassine pour vivre. Tout change.","The starter does not stay in the pan. By morning it is in the hedgerow; by evening it is in the soil. It is still, technically, doing what it was asked.":"Le ferment ne reste pas dans la bassine. Au matin il est dans la haie ; au soir il est dans la terre. Techniquement, il fait toujours ce qu’on lui a demandé.","Throw out the batch and start again?":"Jeter la fournée et tout recommencer ?","This page cannot store a save. Nothing is lost while the tab stays open.":"Cette page ne peut rien sauvegarder. Rien n’est perdu tant que l’onglet reste ouvert.","You can spread the word.":"Vous pouvez faire parler de vous.","Your palate: {0}":"Votre palais : {0}","Your sellers get to {0} of the {1} jars a second people want. Everyone else has to come to the door.":"Vos vendeurs touchent {0} des {1} pots par seconde que les gens réclament. Les autres doivent venir frapper à la porte.","they A":"eux A","they B":"eux B","you A":"vous A","you B":"vous B","Gave up waiting":"Repartis sans acheter","No jars to sell":"Aucun pot à vendre","Nobody at the door":"Personne à la porte","Nobody at the door.":"Personne à la porte.","Sell {0} jars":"Vendre {0} pots","The door":"La porte","This crowd wants":"Cette clientèle veut","Waiting to buy":"En attente d’acheter","Serve whoever is standing at the door. You can only sell to somebody who is actually there, so the asking price decides how often that happens.":"Servez qui se présente à la porte. On ne vend qu’à quelqu’un qui est vraiment là : c’est donc le prix demandé qui décide de la fréquence.","People your sellers cannot reach walk up to the house instead. A lower price brings more of them, and none of them wait very long.":"Ceux que vos vendeurs n’atteignent pas viennent jusqu’à la maison. Un prix plus bas en fait venir davantage, et aucun n’attend bien longtemps.","More sugar. What the crowd wants depends on what you charge — the band below is their tolerance, the line is where you are.":"Plus de sucre. Ce que veut la clientèle dépend de votre prix : la bande ci-dessous est sa tolérance, le trait indique où vous en êtes.","Less sugar. Cheaper per jar, and dearer jam sells to people who would rather taste fruit.":"Moins de sucre. Moins cher par pot, et une confiture chère se vend à des gens qui préfèrent goûter le fruit.","Everything is running at triple for {0}s.":"Tout tourne au triple pendant {0} s.","Larder empty":"Réserve vide","A wasp":"Une guêpe","A bee":"Une abeille","A loose spore":"Une spore égarée","A Pinch of Sulphur":"Une pincée de soufre","You have thrown away enough now to know exactly how it goes wrong. Spoilage runs at two-fifths of its old rate.":"Vous en avez assez jeté pour savoir exactement comment cela tourne mal. Les pertes tombent aux deux cinquièmes.","A jar with a curve that wastes no space against the next jar. Nothing is lost to air any more, anywhere. All machinery works six times as hard.":"Un pot dont la courbe ne perd pas un millimètre contre le pot voisin. Plus rien n’est cédé à l’air, nulle part. Toute la machinerie travaille six fois plus.","A model of what the panel thinks you think of them. Then of what they think you think they think. It goes further than that, and past a certain point it stops being polite to say how far. Earns one taste.":"Un modèle de ce que le panel croit que vous pensez de lui. Puis de ce qu’il croit que vous croyez qu’il pense. Cela va plus loin encore, et passé un certain point il devient malpoli de dire jusqu’où. Rapporte un point de goût.","A vat is room to be out of step. What waits between two stages spoils; a vat lets far more of it wait.":"Une cuve, c’est le droit d’être désynchronisé. Ce qui attend entre deux étapes s’abîme ; une cuve permet à bien plus d’attendre.","A vat is room to be out of step: it holds far more between two stages before what is waiting spoils.":"Une cuve, c’est le droit d’être désynchronisé : elle retient bien plus entre deux étapes avant que ce qui attend ne s’abîme.","Bee Lines":"Lignes d’abeilles","The colony works out the shortest path between every flower in the catchment, and then flies it. Pollination is worth more than twice what it was.":"La colonie calcule le plus court chemin entre chaque fleur du bassin, puis le vole. La pollinisation vaut plus du double d’avant.","Bottling lines put jam into jars. Jars are what everything else here is built out of.":"Les lignes de mise en pot versent la confiture dans les pots. Les pots sont la matière dont tout le reste est bâti ici.","Build pan":"Construire une bassine","Cellarage":"Mise en cave","Cool, dark, and further underground than anybody signed off. What waits between stages waits two and a half times as long before it turns.":"Frais, sombre, et plus profond que ce que quiconque a validé. Ce qui attend entre les étapes tient deux fois et demie plus longtemps avant de tourner.","Cold Fill":"Remplissage à froid","The jam is set before it reaches the jar, which removes the last reason to slow down. Bottling lines work five times as hard.":"La confiture est prise avant d’atteindre le pot, ce qui supprime la dernière raison de ralentir. Les lignes travaillent cinq fois plus.","Copper Bottoms":"Fonds de cuivre","Heat arrives everywhere in the pan at the same instant, so nothing at the edge is asked to wait. Setting pans work three times as hard.":"La chaleur arrive partout dans la bassine au même instant : rien, sur le bord, n’a plus à attendre. Les bassines travaillent trois fois plus.","Deep Rooting":"Enracinement profond","The pickers stop working the surface and start working the whole depth of the soil. Pickers work three times as hard.":"Les récolteuses cessent de travailler la surface et prennent toute l’épaisseur du sol. Elles travaillent trois fois plus.","Each buffer holds":"Chaque réserve contient","Every machine costs jars, and each one costs more than the last. Build the stage that is holding the others up.":"Chaque machine coûte des pots, et chacune coûte plus cher que la précédente. Construisez l’étape qui retient les autres.","Every row is walked and written down, and the walking is done by the bottling lines in the hours they are idle. Pickers gain 1.5% for every bottling line you own.":"Chaque rang est parcouru et consigné, et c’est aux lignes de mise en pot de le faire pendant leurs heures creuses. Les récolteuses gagnent 1,5 % par ligne de mise en pot possédée.","Grid Tie":"Raccordement","The cellars are wired to one another, so a full one can lend to an empty one. Storage triples.":"Les caves sont reliées entre elles : une pleine peut prêter à une vide. Le stockage triple.","Hedgerow Survey":"Relevé des haies","It never comes off the boil, so it never has to come back to it. Setting pans work five times as hard.":"Cela ne redescend jamais du bouillon, donc cela n’a jamais à y remonter. Les bassines travaillent cinq fois plus.","Jam waiting":"Confiture en attente","Money is over. Jars are the currency now, and the machinery is built out of them. Pickers bring the orchard in as fruit, the pans set fruit into jam, the lines put jam into jars.":"L’argent, c’est fini. Les pots sont la monnaie, et la machinerie est faite avec. Les récolteuses rentrent le verger sous forme de fruit, les bassines font prendre le fruit en confiture, les lignes mettent la confiture en pot.","One jar, one weight, one label, everywhere at once. Nobody agreed to it and nobody can now disagree. All machinery works forty times as hard.":"Un pot, un poids, une étiquette, partout à la fois. Personne n’y a consenti et plus personne ne peut s’y opposer. Toute la machinerie travaille quarante fois plus.","One row, laid out end to end, that happens to close on itself. Pickers work five times as hard.":"Un seul rang, mis bout à bout, qui se referme sur lui-même. Les récolteuses travaillent cinq fois plus.","Pan Rotation":"Rotation des bassines","The pans follow the light across the day instead of waiting for it. Setting pans gain 6% for every sun trap you own.":"Les bassines suivent la lumière au fil du jour au lieu de l’attendre. Elles gagnent 6 % par piège solaire possédé.","Picked fruit waiting":"Fruit récolté en attente","Pickers bring the standing orchard in as fruit. They cost jars, like everything here does now, and each one costs more than the last.":"Les récolteuses rentrent le verger sur pied sous forme de fruit. Elles coûtent des pots, comme tout ici désormais, et chacune coûte plus cher que la précédente.","Queen Right":"Reine en place","There is a queen, she is laying, and the colony has stopped asking what any of this is for. The swarm grows twice as fast.":"Il y a une reine, elle pond, et la colonie a cessé de demander à quoi tout cela rime. L’essaim croît deux fois plus vite.","Rolling Boil":"Gros bouillon","Setting pans cook picked fruit into jam. Fruit that waits too long turns before it gets there.":"Les bassines font prendre le fruit récolté en confiture. Un fruit qui attend trop tourne avant d’y arriver.","Setting pans":"Bassines","Setting":"Cuisson","Slowest stage":"Étape la plus lente","Somebody once proved that a shape can always be covered by smaller copies of itself. He was not thinking about a shelf of jars. He is now, posthumously. Autospoons quadruple.":"Quelqu’un a démontré qu’une forme peut toujours être recouverte par des copies réduites d’elle-même. Il ne pensait pas à une étagère de pots. Il y pense désormais, à titre posthume. Les cuillères automatiques quadruplent.","Standard Measures":"Mesures normalisées","Standing orchard":"Verger sur pied","The Long Row":"Le long rang","The Night Shift":"L’équipe de nuit","The air is taken out of the jar before the lid goes on. Nothing in there has any further opinions. Bottling lines work three times as hard.":"On retire l’air du pot avant d’y poser le couvercle. Plus rien là-dedans n’a d’avis sur quoi que ce soit. Les lignes travaillent trois fois plus.","The traps are pointed at what is left of the sky after dark. It is less than the sun and it is not nothing. Nights cost far less.":"Les pièges sont braqués sur ce qui reste du ciel une fois la nuit tombée. C’est moins que le soleil et ce n’est pas rien. Les nuits coûtent bien moins cher.","Vacuum Sealing":"Mise sous vide","Vat":"Cuve","Vats":"Cuves","fruit into jam":"le fruit en confiture","jam into jars":"la confiture en pots","orchard into fruit":"le verger en fruit","setting":"la cuisson","A jar with a curve that wastes no space against the next jar. Nothing is lost to air any more, anywhere. All machinery works two and a half times as hard.":"Un pot dont la courbe ne perd pas un millimètre contre le pot voisin. Plus rien n’est cédé à l’air, nulle part. Toute la machinerie travaille deux fois et demie plus.","Heat arrives everywhere in the pan at the same instant, so nothing at the edge is asked to wait. Setting pans work two and a half times as hard.":"La chaleur arrive partout dans la bassine au même instant : rien, sur le bord, n’a plus à attendre. Les bassines travaillent deux fois et demie plus.","It never comes off the boil, so it never has to come back to it. Setting pans work three times as hard.":"Cela ne redescend jamais du bouillon, donc cela n’a jamais à y remonter. Les bassines travaillent trois fois plus.","Nothing is ever carried anywhere. All machinery works three times as hard.":"Plus rien n’est transporté nulle part. Toute la machinerie travaille trois fois plus.","One jar, one weight, one label, everywhere at once. Nobody agreed to it and nobody can now disagree. All machinery works five times as hard.":"Un pot, un poids, une étiquette, partout à la fois. Personne n’y a consenti et plus personne ne peut s’y opposer. Toute la machinerie travaille cinq fois plus.","One row, laid out end to end, that happens to close on itself. Pickers work three times as hard.":"Un seul rang, mis bout à bout, qui se referme sur lui-même. Les récolteuses travaillent trois fois plus.","The air is taken out of the jar before the lid goes on. Nothing in there has any further opinions. Bottling lines work two and a half times as hard.":"On retire l’air du pot avant d’y poser le couvercle. Plus rien là-dedans n’a d’avis sur quoi que ce soit. Les lignes travaillent deux fois et demie plus.","The distinction between orchard and not-orchard is retired. All machinery works four times as hard.":"La distinction entre verger et non-verger est abandonnée. Toute la machinerie travaille quatre fois plus.","The jam is set before it reaches the jar, which removes the last reason to slow down. Bottling lines work three times as hard.":"La confiture est prise avant d’atteindre le pot, ce qui supprime la dernière raison de ralentir. Les lignes travaillent trois fois plus.","The pickers stop working the surface and start working the whole depth of the soil. Pickers work two and a half times as hard.":"Les récolteuses cessent de travailler la surface et prennent toute l’épaisseur du sol. Elles travaillent deux fois et demie plus.","Catchment":"Bassin","{0} of {1} · {2}":"{0} sur {1} · {2}","The orchard is finished in stages. Each one is far bigger than the last, and your machinery grows at about the same pace, so the bar keeps moving. Emptying the last one ends the act.":"Le verger se termine par étapes. Chacune est bien plus vaste que la précédente, et votre machinerie grandit à peu près au même rythme : la barre continue donc d’avancer. Vider la dernière met fin à l’acte."};

let LANG='en';
try{ LANG=localStorage.getItem('the-jam-lang') || (/^fr\b/i.test(navigator.language||'')?'fr':'en'); }catch(e){}

/* t() takes an English string, or a {en,fr} pair for content authored in both. */
function t(x){
  if(x==null)return '';
  if(typeof x==='object')return x[LANG]!==undefined?x[LANG]:x.en;
  if(LANG==='en')return x;
  return DICT[x]!==undefined?DICT[x]:x;
}
/* for strings assembled from parts, e.g. tf('Crate of {0}', 500) */
function tf(str,...a){ return t(str).replace(/\{(\d)\}/g,(m,i)=>a[i]); }

const ORIG=[];
function snapshotStatic(){
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  let n; while(n=w.nextNode()){
    const p=n.parentElement;
    if(!p||p.closest('#recipeList,#log,#cbLog,.log')||['SCRIPT','STYLE'].includes(p.tagName))continue;
    const v=n.nodeValue;
    if(v && v.trim()) ORIG.push([n,v]);
  }
}
function applyStatic(){
  for(const [n,orig] of ORIG){
    const trimmed=orig.trim();
    const tr=t(trimmed);
    n.nodeValue = tr===trimmed ? orig : orig.replace(trimmed,tr);
  }
}
function setLang(l){
  LANG=l;
  try{ localStorage.setItem('the-jam-lang',l); }catch(e){}
  document.documentElement.lang=l;
  applyStatic();
  const b=document.getElementById('langBtn'); if(b)b.textContent=(l==='en'?'FR':'EN');
  /* applyStatic restores each node from its boot snapshot, so any label the
     game has since rewritten has to be rewritten again, after it. */
  if(typeof updateSoundBtn==='function')updateSoundBtn();
  if(typeof updateAutoBtn==='function'&&s&&s.recipes&&s.recipes.standing)updateAutoBtn();
  drawLog(); drawRecipes(true); buildAlloc(); render(0);
}

try{window.DICT=DICT}catch(e){}
